]$json$::jsonb) AS r(slug text, name text, description text, level text, cefr_levels text[],
                     difficulty numeric, estimated_minutes int, ielts_relevant boolean,
                     keywords text[], category text, group_label text, group_order int, sort_order int)
JOIN grammar_categories c ON c.slug = r.category
LEFT JOIN levels l ON l.code = r.level
ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description, level_id = EXCLUDED.level_id,
    cefr_levels = EXCLUDED.cefr_levels, difficulty = EXCLUDED.difficulty,
    -- A topic coming back into the curriculum is a draft again until content is published.
    status = CASE WHEN grammar_topics.status = 'archived' THEN 'draft' ELSE grammar_topics.status END;

